import{_ as t}from"./chunks/asdt1_uart_wiring.B0DXm_r9.js";import{_ as a,o as r,c as s,al as o}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"Sony AS-DT1 LiDAR","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/sony_asdt1.md","filePath":"en/sensor/sony_asdt1.md"}'),n={name:"en/sensor/sony_asdt1.md"};function i(d,e,h,l,p,c){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="sony-as-dt1-lidar" tabindex="-1">Sony AS-DT1 LiDAR <a class="header-anchor" href="#sony-as-dt1-lidar" aria-label="Permalink to &quot;Sony AS-DT1 LiDAR&quot;">​</a></h1><p>The <em>Sony AS-DT1 LiDAR</em> is a multipoint distance sensor that connects to PX4 over a UART/serial port.</p><p>PX4 configures the sensor for binary output and publishes the measurements to the <a href="./../msg_docs/ObstacleDistance"><code>obstacle_distance</code></a> uORB topic.</p><h2 id="supported-modes" tabindex="-1">Supported Modes <a class="header-anchor" href="#supported-modes" aria-label="Permalink to &quot;Supported Modes&quot;">​</a></h2><p>The driver supports the AS-DT1 distance measurement range modes listed below.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Maximum Measurement Distance</th><th>Minimum Frame Interval</th><th>Distance Measurement Points</th></tr></thead><tbody><tr><td>30MSTD</td><td>30 m</td><td>33.33 ms</td><td>576</td></tr><tr><td>30M15F</td><td>30 m</td><td>66.66 ms</td><td>576</td></tr><tr><td>30M30F</td><td>30 m</td><td>33.33 ms</td><td>288</td></tr><tr><td>20M</td><td>20 m</td><td>33.33 ms</td><td>576</td></tr><tr><td>40M</td><td>40 m</td><td>66.66 ms</td><td>576</td></tr></tbody></table><p>The mode is selected using <a href="./../advanced_config/parameter_reference#SENS_ASDT1_MODE">SENS_ASDT1_MODE</a>.</p><h2 id="collision-prevention-output" tabindex="-1">Collision Prevention Output <a class="header-anchor" href="#collision-prevention-output" aria-label="Permalink to &quot;Collision Prevention Output&quot;">​</a></h2><p>The driver publishes the AS-DT1 data to the <a href="./../msg_docs/ObstacleDistance"><code>obstacle_distance</code></a> uORB topic used by <a href="./../computer_vision/collision_prevention">Collision Prevention</a>. The message uses 72 bins at 5 degree increments around the vehicle.</p><p>The AS-DT1 horizontal field of view is about 35 degrees. The driver maps the sensor&#39;s horizontal band into the matching <code>obstacle_distance</code> bins and leaves uncovered directions as no-data. <a href="./../advanced_config/parameter_reference#SENS_ASDT1_ROT">SENS_ASDT1_ROT</a> sets the yaw offset of this field of view relative to vehicle forward.</p><h2 id="hardware-setup" tabindex="-1">Hardware Setup <a class="header-anchor" href="#hardware-setup" aria-label="Permalink to &quot;Hardware Setup&quot;">​</a></h2><p>The sensor can be connected to any unused <em>serial port</em> (UART), such as <code>TELEM2</code>, <code>TELEM3</code>, or <code>GPS2</code>.</p><p>The AS-DT1 uses the 8-pin JST-GH connector for external power and UART. Connect the sensor TX/RX pins to the flight controller UART and share ground between the sensor power supply and flight controller.</p><p><img src="'+t+'" alt="Sony AS-DT1 UART wiring"></p><table tabindex="0"><thead><tr><th>AS-DT1 8-pin Connector</th><th>Function</th><th>Connect To</th></tr></thead><tbody><tr><td>Pin 1</td><td>GND</td><td>External power ground and flight controller serial GND</td></tr><tr><td>Pin 2</td><td>VCC</td><td>External 12 V to 24 V power supply</td></tr><tr><td>Pin 5</td><td>UART TX</td><td>Flight controller serial RX</td></tr><tr><td>Pin 6</td><td>UART RX</td><td>Flight controller serial TX</td></tr></tbody></table><p>The ground from AS-DT1 pin 1 must be common to both the external power supply and the flight controller serial port. For example, splice or split the AS-DT1 ground wire so it connects to the power supply negative terminal and to the flight controller UART <code>GND</code> pin.</p><p>Do not connect the AS-DT1 UART pins directly to RS-232 or RS-422 interfaces. The AS-DT1 UART RX input is 5 V tolerant, and the sensor should be powered from the external 12 V to 24 V supply described in the Sony hardware documentation.</p><h2 id="firmware-setup" tabindex="-1">Firmware Setup <a class="header-anchor" href="#firmware-setup" aria-label="Permalink to &quot;Firmware Setup&quot;">​</a></h2><p>The <code>sony_asdt1</code> driver must be included in the PX4 firmware for the target board. If the Sony AS-DT1 parameters are not available, add the following line to the target board&#39;s <code>default.px4board</code> configuration, or enable the driver using <a href="./../hardware/porting_guide_config#px4-menuconfig-setup"><code>boardconfig</code></a>:</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_DRIVERS_DISTANCE_SENSOR_SONY_ASDT1=y</span></span></code></pre></div><p>Then rebuild and flash the firmware.</p><h2 id="parameter-setup" tabindex="-1">Parameter Setup <a class="header-anchor" href="#parameter-setup" aria-label="Permalink to &quot;Parameter Setup&quot;">​</a></h2><p>Use the Sony application to set the sensor to <strong>Measurement (UART)</strong> mode before connecting it to PX4.</p><p>The driver uses the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#SENS_ASDT1_CFG">SENS_ASDT1_CFG</a></td><td>Selects the serial port and enables driver autostart on boot.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#SENS_ASDT1_MODE">SENS_ASDT1_MODE</a></td><td>Selects the AS-DT1 measurement range mode. The driver configures the sensor mode and publishes matching <code>obstacle_distance</code> metadata.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#SENS_ASDT1_ROT">SENS_ASDT1_ROT</a></td><td>Sets the sensor yaw offset, in degrees, relative to vehicle forward. This is published as <code>obstacle_distance.angle_offset</code>; positive values are clockwise.</td></tr></tbody></table><p><code>SENS_ASDT1_MODE</code> and <code>SENS_ASDT1_ROT</code> may not appear until <code>SENS_ASDT1_CFG</code> is enabled and the flight controller has rebooted once.</p><p>Reboot the flight controller, or restart the driver manually, after changing these parameters.</p><p><a href="./../peripherals/serial_configuration">Configure the serial port</a> on which the sensor will run using <a href="./../advanced_config/parameter_reference#SENS_ASDT1_CFG">SENS_ASDT1_CFG</a>. There is no need to set the baud rate for the port, as this is configured by the driver.</p><p>Set <a href="./../advanced_config/parameter_reference#SENS_ASDT1_MODE">SENS_ASDT1_MODE</a> to the required measurement mode and reboot the flight controller.</p><p>If the sensor is mounted with a yaw offset from vehicle forward, set <a href="./../advanced_config/parameter_reference#SENS_ASDT1_ROT">SENS_ASDT1_ROT</a> to the offset in degrees. Positive values are clockwise.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>You can check the driver state in the <em>QGroundControl MAVLink Console</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sony_asdt1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>You can observe the published measurements with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> obstacle_distance</span></span></code></pre></div><p>To print the sensor&#39;s saved configuration without starting measurements, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sony_asdt1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyS2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span></code></pre></div><p>Replace <code>/dev/ttyS2</code> with the serial device for your board and port.</p><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="./../modules/modules_driver_distance_sensor#sony-asdt1">Modules Reference: Distance Sensor (Driver): sony_asdt1</a></li></ul>',40)])])}const f=a(n,[["render",i]]);export{S as __pageData,f as default};
